def clean(df):
    species_mapping = {
        'adelie': 'Adelie',
        'gentoo': 'Gentoo',
        'gentto': 'Gentoo',
        'chinstrap': 'Chinstrap'
    }
    df['species'] = df['species'].replace(species_mapping)
    df['body_mass_g'] = df['body_mass_g'].str.replace(',', '').astype(float)
    return df

def answer(df):
    return df.groupby('species')['body_mass_g'].mean().to_dict()
